```
func (t *funcTool[Args, Results]) create(*createContext) (tool.Tool, error) {
	cfg := functiontool.Config{
		Name:        t.Name,
		Description: t.Description,
	}
	toolFn := func(ctx tool.Context, args Args) Results {
		ectx := ctx.Value(executeContextKey).(Context)
		res, err := t.Func(ectx, args)
		if err != nil {
			panic(toolError{err})
		}
		return res
	}
	ft, err := functiontool.New(cfg, toolFn)
	if err != nil {
		return nil, err
	}
	return &funcToolWrapper{ft}, nil
}

type funcToolWrapper struct {
	tool.Tool
}

type toolError struct {
	err error
}

func (f *funcToolWrapper) Run(ctx tool.Context, args any) (res map[string]any, resErr error) {
	defer func() {
		if err := recover(); err != nil {
			if te, ok := err.(toolError); ok {
				resErr = te.err
				return
			}
			panic(err)
		}
	}()
	type toolRunner interface {
		Run(tool.Context, any) (map[string]any, error)
	}
	return f.Tool.(toolRunner).Run(ctx, args)
}

func (f *funcToolWrapper) ProcessRequest(ctx tool.Context, req *model.LLMRequest) error {
	type requestProcessor interface {
		ProcessRequest(ctx tool.Context, req *model.LLMRequest) error
	}
	return f.Tool.(requestProcessor).ProcessRequest(ctx, req)
}
```

## **Bug Details**
Using `by llm(..., tools=([...]))` with node methods (e.g., `self.add`) raises an error:

```
ERROR - 'method' object has no attribute '__annotations__'
```
But the same function works correctly if declared in the global scope.

### **To Reproduce**
```py
import from mtllm.llm { Model }

glob llm = Model(model_name="gpt-4o-mini", verbose=False);

node Calculator {
    def add(num1: int, num2: int) -> int {
        print("adding numbers");
        return num1 + num2;
    }

    def select_and_run(expression: str) -> str by llm(
        method="ReAct",
        tools=([self.add])   # ❌ fails here
    );
    can execute with calculation_walker entry {
        print("Answer: ", self.select_and_run(visitor.expression));
    }
}

walker calculation_walker {
    has expression: str = "";
}

with entry {
    calc = Calculator();
    calculation_walker("Can you tell me the answer of 2+3?") spawn calc;
}
```

Error output
```
ERROR - 'method' object has no attribute '__annotations__'
```

### **Workaround (Works as Expected)**

If the function is declared in global scope, it works fine:

```py
import from mtllm.llm { Model }

glob llm = Model(model_name="gpt-4o-mini", verbose=False);

def add(num1: int, num2: int) -> int {
    print("adding numbers");
    return num1 + num2;
}

node Calculator {
    def select_and_run(expression: str) -> str by llm(
        method="ReAct",
        tools=([add])   # ✅ works
    );
    can execute with calculation_walker entry {
        print("Answer: ", self.select_and_run(visitor.expression));
    }
}

walker calculation_walker {
    has expression: str = "";
}

with entry {
    calc = Calculator();
    calculation_walker("Can you tell me the answer of 2+3?") spawn calc;
}
```

### **Expected Behavior**
Node methods (like `self.add`) should be supported as tools in `by llm`, the same way global functions are.

### **Actual Behavior**
- Passing a node method as a tool fails with `__annotations__` error.
- Passing a global function works correctly.

