          maxLatency: 100,
          throughput: 10000
        }
      }
    };
  }

  async handleTask(task: A2ATask): Promise<TaskResult> {
    // Create task in state machine
    const taskId = await this.taskManager.createTask({
      id: task.id || this.generateTaskId(),
      capability: task.capability,
      parameters: task.parameters,
      requester: task.requester,
      priority: task.priority || 'normal',
      deadline: task.deadline,
      paymentMandate: task.paymentMandate
    });

    // Transition to VALIDATED state
    await this.taskManager.transitionState(taskId, TaskState.VALIDATED);

    // Find executor for capability
    const executor = await this.findExecutor(task.capability);
    if (!executor) {
      await this.taskManager.transitionState(taskId, TaskState.FAILED);
      throw new CapabilityNotFoundError(task.capability);
    }

    // Transition to ASSIGNED state
    await this.taskManager.transitionState(taskId, TaskState.ASSIGNED);

    // Check payment requirement
    if (executor.requiresPayment) {
      await this.taskManager.transitionState(taskId, TaskState.PAYMENT_PENDING);

      const paymentVerified = await this.verifyPayment(task.paymentMandate);
      if (!paymentVerified) {
        await this.taskManager.transitionState(taskId, TaskState.FAILED);
        throw new PaymentRequiredError(executor.pricing);
      }
    }

    // Execute task
    await this.taskManager.transitionState(taskId, TaskState.WORKING);

    try {
      const result = await executor.execute(task.parameters);

      await this.taskManager.transitionState(taskId, TaskState.COMPLETED);

      return {
        taskId: taskId,
        status: 'completed',
        result: result,
        executionTime: Date.now() - task.startTime,
        executor: executor.id
      };

    } catch (error) {
      await this.taskManager.transitionState(taskId, TaskState.FAILED);
      throw error;
    }
  }
}

// Task Lifecycle Manager
export class TaskLifecycleManager {
  private tasks: Map<string, TaskRecord>;
  private stateStore: SQLiteStateStore;
  private eventEmitter: EventEmitter;

  async transitionState(taskId: string, newState: TaskState): Promise<void> {
    const task = this.tasks.get(taskId);
    if (!task) {
      throw new Error(`Task ${taskId} not found`);
    }

    // Validate state transition
    if (!this.isValidTransition(task.state, newState)) {
      throw new InvalidStateTransitionError(task.state, newState);
    }

    // Update state
    task.state = newState;
    task.stateHistory.push({
      state: newState,
      timestamp: Date.now(),
      metadata: this.captureStateMetadata(newState)
    });

    // Persist to database
    await this.stateStore.updateTaskState(taskId, newState);

    // Emit state change event
    this.eventEmitter.emit('stateChange', {
      taskId: taskId,
      previousState: task.state,
      newState: newState
    });
  }

  private isValidTransition(current: TaskState, next: TaskState): boolean {
    const validTransitions = {
      [TaskState.SUBMITTED]: [TaskState.VALIDATED, TaskState.FAILED],
      [TaskState.VALIDATED]: [TaskState.ASSIGNED, TaskState.FAILED],
      [TaskState.ASSIGNED]: [TaskState.WORKING, TaskState.PAYMENT_PENDING, TaskState.FAILED],
      [TaskState.PAYMENT_PENDING]: [TaskState.WORKING, TaskState.FAILED],
      [TaskState.WORKING]: [TaskState.INPUT_REQUIRED, TaskState.COMPLETED, TaskState.FAILED],
      [TaskState.INPUT_REQUIRED]: [TaskState.WORKING, TaskState.FAILED],
      [TaskState.COMPLETED]: [TaskState.DISPUTED],
      [TaskState.FAILED]: [],
      [TaskState.DISPUTED]: [TaskState.COMPLETED, TaskState.FAILED]
    };

    return validTransitions[current]?.includes(next) || false;
  }
}
