export class ProtocolTranslator {
  private schemaMapper: SchemaMapper;
  private semanticAnalyzer: SemanticAnalyzer;
  private translationCache: LRUCache<string, TranslationResult>;

  constructor() {
    this.schemaMapper = new SchemaMapper();
    this.semanticAnalyzer = new SemanticAnalyzer();

    this.translationCache = new LRUCache({
      max: 10000,
      ttl: 300000,  // 5 minute TTL
      updateAgeOnGet: true
    });
  }

  async translateMCPToA2A(mcpTool: MCPTool): Promise<A2ACapability> {
    const cacheKey = `mcp-a2a:${mcpTool.name}:${mcpTool.version}`;
    const cached = this.translationCache.get(cacheKey);
    if (cached) {
      return cached as A2ACapability;
    }

    const startTime = performance.now();

    const capability: A2ACapability = {
      name: mcpTool.name,
      description: mcpTool.description,
      version: mcpTool.version || '1.0.0',

      // Schema translation
      inputSchema: this.translateJSONSchemaToA2A(mcpTool.inputSchema),
      outputSchema: this.translateJSONSchemaToA2A(mcpTool.outputSchema),

      // Semantic analysis for categorization
      categories: await this.semanticAnalyzer.categorize(mcpTool.description),

      // Performance characteristics
      performance: {
        estimatedLatency: this.estimateLatency(mcpTool),
        throughput: this.estimateThroughput(mcpTool),
        concurrency: mcpTool.maxConcurrency || 100
      },

      // Pricing model
      pricing: {
        model: 'per_execution',
        basePrice: this.calculateBasePrice(mcpTool),
        currency: 'USD',
        freeQuota: 100
      },

      // SLA guarantees
      sla: {
        availability: 0.999,
        maxLatency: 1000,
        supportedRegions: ['global']
      },

      // Preserve MCP metadata
      _mcp: {
        originalTool: mcpTool,
        toolId: mcpTool.id,
        requiresContext: mcpTool.requiresContext
      }
    };

    const translationTime = performance.now() - startTime;
    if (translationTime > 10) {
      console.warn(`Translation exceeded 10ms target: ${translationTime}ms`);
    }

    this.translationCache.set(cacheKey, capability);
    return capability;
  }

  async translateA2AToMCP(task: A2ATask): Promise<MCPToolCall> {
    const cacheKey = `a2a-mcp:${task.capability}:${JSON.stringify(task.parameters)}`;
    const cached = this.translationCache.get(cacheKey);
    if (cached) {
      return cached as MCPToolCall;
    }

    // Find matching MCP tool
    const tool = await this.findMatchingMCPTool(task.capability);
    if (!tool) {
      throw new NoMatchingToolError(task.capability);
    }

    // Translate parameters
    const mcpParams = this.translateParameters(task.parameters, tool.inputSchema);

    const toolCall: MCPToolCall = {
      tool: tool.name,
      arguments: mcpParams,
      context: {
        originalTask: task,
        taskId: task.id,
        requester: task.requester,
        paymentMandate: task.paymentMandate
      }
    };

    this.translationCache.set(cacheKey, toolCall);
    return toolCall;
  }

  private translateJSONSchemaToA2A(schema: any): any {
    // Deep clone to avoid mutation
    const translated = JSON.parse(JSON.stringify(schema));

    // A2A specific schema enhancements
    if (translated.type === 'object' && translated.properties) {
      for (const [key, value] of Object.entries(translated.properties)) {
        // Add A2A metadata
        (value as any)._a2a = {
          required: translated.required?.includes(key),
          sensitive: this.isSensitiveField(key),
          validation: this.generateValidation(value)
        };
      }
    }

    return translated;
  }
}
```

