```typescript
// File: src/monitoring/protocol-metrics.ts
// Context: Comprehensive metrics collection for protocol bridge performance
// Requirements: Must expose Prometheus-compatible metrics endpoint

export class ProtocolMetrics {
  private prometheusRegistry: Registry;
  private metrics: {
    translationLatency: Histogram;
    protocolRequests: Counter;
    paymentVolume: Counter;
    consensusLatency: Histogram;
    cacheHitRate: Gauge;
    activeConnections: Gauge;
    sqliteOpsPerSecond: Gauge;
  };

  constructor() {
