        labelNames: ['protocol', 'status']
      }),

      paymentVolume: new Counter({
        name: 'payment_volume_usd',
        help: 'Total payment volume in USD',
        labelNames: ['currency', 'status']
      }),

      consensusLatency: new Histogram({
        name: 'consensus_latency_ms',
        help: 'Byzantine consensus latency in milliseconds',
        labelNames: ['algorithm'],
        buckets: [10, 50, 100, 250, 500, 1000, 2500, 5000]
      }),

      cacheHitRate: new Gauge({
        name: 'cache_hit_rate',
        help: 'Translation cache hit rate',
        labelNames: ['cache_type']
      }),

      activeConnections: new Gauge({
        name: 'active_connections',
        help: 'Number of active protocol connections',
        labelNames: ['protocol']
      }),

      sqliteOpsPerSecond: new Gauge({
        name: 'sqlite_operations_per_second',
        help: 'SQLite operations per second',
        labelNames: ['operation_type']
      })
    };

    // Register all metrics
    Object.values(this.metrics).forEach(metric => {
      this.prometheusRegistry.registerMetric(metric);
    });

    // Start metrics collection
    this.startMetricsCollection();
  }

  private startMetricsCollection(): void {
    // Update SQLite ops/sec every second
    setInterval(() => {
      const opsPerSecond = this.calculateSQLiteOpsPerSecond();
      this.metrics.sqliteOpsPerSecond.set({ operation_type: 'all' }, opsPerSecond);

      // Alert if below target
      if (opsPerSecond < 350000) {
        console.error(`SQLite performance degraded: ${opsPerSecond} ops/sec`);
      }
    }, 1000);

    // Update cache hit rate every 10 seconds
    setInterval(() => {
      const hitRate = this.calculateCacheHitRate();
      this.metrics.cacheHitRate.set({ cache_type: 'translation' }, hitRate);
    }, 10000);
  }

  async getMetrics(): Promise<string> {
    return this.prometheusRegistry.metrics();
  }
}
